import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { refreshSessionHandler } from "../handlers/refreshSessionHandler";
import type { ApiError } from "../runtime/client";
import type { RefreshSessionRequest } from "../types/RefreshSessionRequest";

type Data = Awaited<ReturnType<typeof refreshSessionHandler>>;
type Vars = RefreshSessionRequest;

export function useRefreshSession(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => refreshSessionHandler(vars),
    ...options,
  });
}
